import json
from pathlib import Path
rows=[]
def q(lang,tag,text,options,correct,explanation):
    rows.append(dict(id=f'{lang}-q{len([r for r in rows if r["language"]==lang])+1}',language=lang,tag=tag,text=text,options=options,correct=correct,explanation=explanation))
q('python','start','Что покажет print("Привет")?',['Привет','"Привет"','Ничего: нужна переменная'],0,'print выводит содержимое строки, без кавычек.')
q('python','variables','После x = 3 и x = x + 2 чему равен x?',['3','5','Возникнет ошибка'],1,'Правая часть использует прежнее 3, затем результат 5 сохраняется в x.')
q('python','types','Как превратить строку "12" в целое число?',['str("12")','int("12")','"12" + 0'],1,'int преобразует подходящую строку в число, а str создаёт строку.')
q('python','conditions','Какое условие истинно при age = 18?',['age > 18','age < 18','age >= 18'],2,'Оператор >= включает саму границу.')
q('python','loops','Какие значения даёт range(1, 4)?',['1, 2, 3, 4','1, 2, 3','0, 1, 2, 3'],1,'Правая граница range не включается.')
q('python','collections','Как получить первый элемент names?',['names[1]','names[0]','names.first()'],1,'Индексация списков начинается с нуля.')
q('python','functions','Что возвращает функция без return?',['Последнее напечатанное число','Ничего: это всегда ошибка','None'],2,'Функция без явного return возвращает None; print не заменяет return.')
q('python','objects','Где хранить отдельный счётчик каждого объекта?',['В self.value внутри __init__','В одной общей глобальной переменной','Только в имени класса'],0,'Атрибут экземпляра self.value принадлежит конкретному объекту.')
q('sql','start','Что представляет одна строка таблицы users?',['Один столбец','Одного пользователя','Все таблицы базы'],1,'Строка — запись; столбцы описывают её свойства.')
q('sql','select','Как прочитать только имена из users?',['SELECT name FROM users;','GET users.name;','SELECT users FROM name;'],0,'SELECT перечисляет столбцы, FROM указывает таблицу.')
q('sql','where','Как проверить отсутствие department_id?',['department_id = NULL','department_id IS NULL','department_id = 0'],1,'NULL проверяют через IS NULL; ноль является обычным значением.')
q('sql','order','Что гарантирует порядок строк по возрасту?',['Сам SELECT','ORDER BY age','Название таблицы'],1,'Без ORDER BY порядок результата не гарантируется.')
q('sql','aggregate','В чём разница COUNT(*) и COUNT(age)?',['Разницы никогда нет','COUNT(age) не считает NULL','COUNT(*) считает столбцы'],1,'COUNT(*) считает строки, COUNT(age) — ненулевые значения age.')
q('sql','write','Что сделает UPDATE users SET active=0 без WHERE?',['Обновит все строки','Только первую строку','Ничего'],0,'Без WHERE обновление применяется ко всем строкам таблицы.')
q('sql','schema','Как запретить повторяющиеся непустые email?',['Только TEXT','NOT NULL UNIQUE','ORDER BY email'],1,'NOT NULL запрещает отсутствие, UNIQUE — дубликаты.')
q('sql','join','Что сохраняет LEFT JOIN при отсутствии совпадения справа?',['Левую строку с NULL справа','Только правую строку','Ничего'],0,'LEFT JOIN сохраняет все строки левой таблицы.')
q('postgresql','start','Что такое PGlite в DevForge?',['Другое имя SQLite','PostgreSQL в WebAssembly','Облачный сервис'],1,'PGlite использует PostgreSQL, собранный для WebAssembly; это локальная учебная среда.')
q('postgresql','types','Какое значение подходит столбцу BOOLEAN?',['TRUE','Только 1 как INTEGER','Любая строка'],0,'У PostgreSQL есть отдельный тип BOOLEAN.')
q('postgresql','types','Что делает \'42\'::integer?',['Создаёт таблицу','Преобразует текст в целое число','Печатает ::integer'],1,'Оператор :: явно преобразует тип.')
q('postgresql','where','Какой оператор ищет текст без учёта регистра?',['ILIKE','LIKE всегда','EQUALS'],0,'ILIKE — регистронезависимый вариант сравнения по шаблону.')
q('postgresql','write','Для чего нужен INSERT ... RETURNING id?',['Получить id вставленной записи','Удалить id','Отменить вставку'],0,'RETURNING возвращает данные изменённых строк.')
q('postgresql','json','Какой оператор JSONB возвращает текст поля?',['->','->>','=>'],1,'->> извлекает текст; -> сохраняет JSON-представление.')
q('postgresql','subquery','Как долго существует имя CTE из WITH?',['В рамках одного SQL-выражения','До удаления всей базы','Всегда'],0,'CTE — именованный промежуточный результат одного запроса.')
q('postgresql','window','Что отличает оконную функцию от GROUP BY?',['Она всегда удаляет строки','Она сохраняет отдельные строки','Она не может сортировать'],1,'Оконные функции добавляют вычисления к строкам, не объединяя их в одну запись группы.')
q('html-css','start','Что задаёт HTML?',['Структуру страницы','Только цвет текста','Версию базы данных'],0,'HTML описывает элементы и их смысл. CSS отвечает за внешний вид.')
q('html-css','structure','Какой тег обозначает главный заголовок?',['<p>','<h1>','<style>'],1,'h1 — заголовок первого уровня.')
q('html-css','structure','Где находится видимое содержимое документа?',['В body','Только в title','Только в head'],0,'body содержит видимые элементы; head — метаданные.')
q('html-css','css','Как CSS выбирает class="note"?',['note','.note','#note'],1,'Точка обозначает селектор класса, # — id.')
q('html-css','css','Какое свойство меняет цвет текста?',['background','color','display'],1,'color отвечает за цвет текста, background — за фон.')
q('html-css','layout','Что такое padding?',['Внутренний отступ','Внешний отступ','Толщина букв'],0,'Padding отделяет содержимое от рамки; margin — от соседей.')
q('html-css','layout','Где задают display:flex?',['На контейнере','Только на тексте','В теге title'],0,'Flex-контейнер управляет расположением своих дочерних элементов.')
q('html-css','accessibility','Как связать label с input id="name"?',['label for="name"','label href="name"','Совпадения текста достаточно'],0,'for у label должен совпасть с id поля.')
(Path(__file__).resolve().parents[1]/'content/assessment.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
print(len(rows),'assessment questions')
